pub type DateInputHandler = Rc<RefCell<dyn FnMut(i32, u32) + 'static>>;

/// A node in the retained view tree (the application's canonical UI tree).
#[derive(Clone, PartialEq)]
pub struct Node {
    /// Stable node id (0 until `assign_ids`).
