            let h_other = hadj.clone();
            vadj.connect_value_changed(move |adj| {
                v_sink.borrow_mut()(Event::Scroll {
                    target,
                    offset_x: h_other.value() as f32,
                    offset_y: adj.value() as f32,
                });
