    let alignment = node
        .properties
        .get(&property_id::ALIGNMENT)
        .map(|bits| f32::from_bits(*bits) as u8)
        .unwrap_or(3);
    let align = match alignment {
        0 => "flex-start",
        1 => "center",
        2 => "flex-end",
        _ => "flex-start",
